function rabbisPage(){return pageTitle('Kehilla · קהילה','71 Namen. 71 Gesichter.','Die vorhandenen Projektfiguren begleiten den gesamten Jahresablauf. Die Porträts sind keine historische Rabbinerliste.')+`<div class="toolbar"><input type="search" id="rabbi-search" placeholder="Rabbiner nach Namen suchen …" aria-label="Rabbiner suchen"><span class="tag">71 Porträts · aus dem Sanhedrin-Bestand</span></div><div class="gallery">${data.rabbis.map((r,i)=>`<button class="person" data-rabbi="${i}" data-search="${esc(r.name.toLowerCase())}"><img src="${r.portrait||r.image}" alt="${esc(r.name)}" loading="lazy" width="210" height="240"><span class="person-copy"><strong>${esc(r.name)}</strong><small>${i===leaderIndex()?'Heute: Vorbeter':i===(info.hd.abs()+2)%71?'Heute: Gabbai':`Gemeindemitglied ${String(i+1).padStart(2,'0')}`}</small></span></button>`).join('')}</div>`+footer()}
function originalSiddurPage(){const doc=data.rashash.documents.find(d=>d.id===state.pdf)||data.rashash.documents[0];const sec=data.siddur[state.section]||data.siddur[0];return pageTitle('Tefilla weKavvana · תפילה וכוונה','Der Siddur im Mittelpunkt.','Rashash im Originalscan. Ergänzende Gebetstexte im Nusach Edot HaMizrach.')+`<div class="service-tabs"><button data-siddur-mode="rashash-text">HaRashash · Text mit Niqqud</button><button data-siddur-mode="rashash" class="${state.siddurMode==='rashash'?'active':''}">Siddur HaRashash · Original</button><button data-siddur-mode="edot" class="${state.siddurMode==='edot'?'active':''}">Edot HaMizrach · lesbarer Text</button></div>`+(state.siddurMode==='rashash'?`<div class="toolbar">${hasRashashTextPage(doc.transcription,state.pdfPage===2?3:state.pdfPage)?`<button class="smallbtn" data-open-rashash-text="${doc.id}" data-page="${state.pdfPage===2?3:state.pdfPage}">Diese Seite als Text mit Niqqud →</button>`:''}<select id="pdf-select" aria-label="Rashash-Scan wählen" style="max-width:100%">${data.rashash.documents.map(d=>`<option value="${d.id}" ${d.id===doc.id?'selected':''}>${esc(d.title)}</option>`).join('')}</select><label>PDF-Seite <input type="number" min="1" max="${doc.pages}" value="${state.pdfPage}" id="pdf-page" style="width:80px"></label><a href="${esc(assetUrl(doc.path))}#page=${state.pdfPage}" target="_blank" rel="noopener" class="download">Original separat öffnen ↗</a></div><div class="split"><aside class="catalog"><h3 style="color:var(--gold);margin-bottom:10px">Themen in diesem Scan</h3>${doc.topics.map(t=>`<button data-pdf-page="${t.page}" class="${state.pdfPage===t.page?'active':''}" style="text-align:left;direction:ltr;font:13px Assistant,sans-serif">${esc(t.label)} <small>· PDF ${t.page}</small></button>`).join('')}<div class="notice">${esc(doc.note)}</div><a href="${doc.source}" target="_blank" rel="noopener">HebrewBooks · Originalquelle ↗</a></aside><section><iframe class="pdf-frame" title="${esc(doc.title)} · Seite ${state.pdfPage}" src="${esc(assetUrl(doc.path))}#page=${state.pdfPage}&view=FitH"></iframe><p class="copyright">Falls dein Browser den Scan nicht einbettet, öffne ihn über „Original separat öffnen“. Die Seitenangaben zählen PDF-Seiten einschließlich Vorblättern.</p></section></div><div class="notice">Die Kavvanot werden als Originalquelle zugänglich gemacht. Der animierte Gebetsablauf ist keine geprüfte Transkription aller Rashash-Kavvanot; fehlende Festtexte werden nicht als Rashash-Text ergänzt.</div>`:`<div class="toolbar"><input type="search" id="siddur-search" placeholder="Hebräischen Titel oder Text suchen …" aria-label="Siddur durchsuchen"><span class="tag">${data.siddur.length} Textabschnitte · Shaliehsaboo Edition</span></div><div class="split"><aside class="catalog" id="siddur-catalog">${data.siddur.map(s=>`<button data-section="${s.id}" class="${s.id===state.section?'active':''}" data-search="${esc((s.title+' '+s.html.replace(/<[^>]+>/g,' ')).toLowerCase())}">${esc(s.title)}</button>`).join('')}</aside><article class="reader"><div class="source-line">Edot HaMizrach · Shaliehsaboo Edition · Sefaria (CC0) · <a href="https://www.sefaria.org/Siddur_Edot_HaMizrach" target="_blank" rel="noopener">Quelle ↗</a></div><h3>${esc(sec.title)}</h3><div style="margin-bottom:15px"><button data-action="speak-section">♪ Künstliche Lesestimme</button> <button data-action="stop-audio">■ Stopp</button></div><div class="reader-body">${sec.html}</div></article></div><div class="notice">Der Originaltext enthält Varianten und jahreszeitliche Anweisungen. Sie bleiben sichtbar; die Textansicht entfernt keine Alternativfassungen automatisch.</div>`)+footer()}
const rashashStore=new RashashTextStore(),rashashTextErrors=new Map(),rashashTextLoading=new Set();
function siddurPage(){
 if(state.siddurMode!=='rashash-text')return originalSiddurPage();
 return pageTitle('Tefilla weKavvana · תפילה וכוונה','Siddur HaRashash zum Mitlesen.','Die transkribierten Bände in Quadratschrift, mit ergänztem Niqqud und erhaltenen Quellenverweisen.')+`<div class="service-tabs"><button data-siddur-mode="rashash-text" class="active">HaRashash · Text mit Niqqud</button><button data-siddur-mode="rashash">Siddur HaRashash · Original</button><button data-siddur-mode="edot">Edot HaMizrach · lesbarer Text</button></div>`+renderRashashReader({documents:data.rashash.documents,id:state.textVolume,pageNumber:state.textPage,volume:rashashStore.get(state.textVolume),error:rashashTextErrors.get(state.textVolume),fontSize:state.readFont})+footer();
}
function loadRashashText(){
 const id=state.textVolume,metadata=data.rashash.documents.find(d=>d.id===id)?.transcription;
 if(!metadata||rashashStore.get(id)||rashashTextErrors.has(id)||rashashTextLoading.has(id))return;
 rashashTextLoading.add(id);rashashStore.load(metadata).catch(error=>rashashTextErrors.set(id,error.name==='AbortError'?'Das Laden hat zu lange gedauert. Bitte erneut versuchen.':error.message)).finally(()=>{rashashTextLoading.delete(id);if(state.page==='siddur'&&state.siddurMode==='rashash-text'&&state.textVolume===id)render();});
}
function openRashashText(id,page=1){state.textVolume=id;state.textPage=page;state.siddurMode='rashash-text';if($('#modal').open)$('#modal').close();navigate('siddur');}
function moveRashashText(delta){const volume=rashashStore.get(state.textVolume);if(!volume)return;const index=Math.max(0,volume.pages.findIndex(p=>p.pdfPage===state.textPage));state.textPage=volume.pages[Math.max(0,Math.min(volume.pages.length-1,index+delta))].pdfPage;render();}

const readLoader=new ReadAlongLoader();let readToken=0;
let readState={key:'',status:'idle',descriptor:null,error:''};let readBindings={};try{readBindings=JSON.parse(localStorage.getItem('azara-reading-bindings')||'{}')}catch{}
function readingBody(){const d=readState.descriptor;if(readState.status==='loading')return '<div class="reading-empty" role="status">Die passende Textpassage wird geöffnet …<small>Die Aufnahme startet, sobald der Text bereitsteht.</small></div>';if(readState.status==='error')return `<div class="reading-empty">Der Text konnte momentan nicht geladen werden.<small>${esc(readState.error)}</small><button data-action="read-retry">Text erneut laden</button>${d?.sourceUrl?`<a href="${esc(d.sourceUrl)}" target="_blank" rel="noopener">Originaltext öffnen ↗</a>`:''}</div>`;if(!d)return `<div class="reading-empty">${audio.current?'Für diese Aufnahme ist noch keine eindeutige Textpassage hinterlegt.':'Starte eine Aufnahme, um automatisch mitzulesen.'}<small>${audio.current?'Wähle die passende Passage rechts. Sie wird für diese Aufnahme in deinem Browser gemerkt.':'Gebet, Tora oder Haftara: Der Text öffnet sich zusammen mit dem Ton.'}</small></div>`;if(d.passages)return d.passages.map(p=>`<section class="reading-passage"><h3 dir="ltr">${esc(p.ref)}</h3>${p.verses.map(v=>`<p class="reading-verse"><span class="verse-number">${esc(v.label)}</span>${esc(v.text)}</p>`).join('')}</section>`).join('');if(d.text)return d.text.split(/\n+/).filter(x=>x.trim()).map(x=>`<p>${esc(x)}</p>`).join('');return (d.html||'').trim().split(/\n+/).filter(x=>x.trim()).map(x=>`<div class="reading-paragraph">${x}</div>`).join('');}
function readingStatus(){if(readState.status==='loading')return 'Text wird vorbereitet';if(!audio.current)return 'Keine Aufnahme läuft';return audio.audio.paused?'Aufnahme pausiert':'Aufnahme läuft';}
function readAlongPage(){const d=readState.descriptor;return pageTitle('Kol weSiddur · קול וסידור','Hören. Mitlesen.','Die Textpassage folgt automatisch der laufenden Aufnahme. Vorerst mit Nusach Edot HaMizrach und den biblischen Originaltexten.',`<button class="smallbtn ghost" data-nav="scene">Zur Synagoge →</button>`)+`<div class="readalong-layout"><article class="readalong-book"><header class="readalong-heading"><div><div class="eyebrow">Mitlesetext</div><h2 id="reading-title">${esc(d?.title||audio.current?.title||'Dein Siddur zum Hören')}</h2><p id="reading-source">${esc(d?.source||'Die Passage öffnet sich mit der Aufnahme.')}</p></div><div class="reading-font"><button data-action="read-smaller" aria-label="Schrift verkleinern">A−</button><button data-action="read-larger" aria-label="Schrift vergrößern">A+</button></div></header><div id="reading-body" class="reading-body he" tabindex="0" aria-label="Text zur laufenden Aufnahme" style="--reading-size:${state.readFont}px">${readingBody()}</div><footer class="reading-source-footer"><span id="reading-note">${esc(d?.note||'')}</span><a id="reading-original" href="${esc(d?.sourceUrl||'https://www.sefaria.org/Siddur_Edot_HaMizrach')}" target="_blank" rel="noopener">Originaltext ↗</a></footer></article><aside class="readalong-controls"><div class="card"><div class="eyebrow"><span class="status-dot"></span>Ton & Text</div><h3 id="reading-track-name" style="margin-top:9px">${esc(audio.current?.title||audio.current?.canonical||'Wähle eine Aufnahme')}</h3><p id="reading-status" role="status">${readingStatus()}</p><div class="reading-clock"><strong id="reading-time">0:00</strong><span id="reading-duration">/ –</span></div><div class="progress"><i id="reading-progress"></i></div><button class="primary reading-play-toggle" id="reading-play-toggle" data-action="read-toggle" ${audio.current?'':'disabled'}>${audio.preparing||!audio.audio.paused?'Ⅱ Pause':'▶ Fortsetzen'}</button><div class="reading-queue"><button class="smallbtn" data-action="read-previous" ${audio.index>0?'':'disabled'}>← Aufnahme</button><span id="reading-queue-count">${audio.current?`${audio.index+1} / ${audio.queue.length}`:'–'}</span><button class="smallbtn" data-action="read-next" ${audio.index+1<audio.queue.length?'':'disabled'}>Aufnahme →</button></div><label class="settings-row"><input type="checkbox" id="follow-toggle" ${state.followAudio?'checked':''}>Mitlesetext automatisch öffnen</label><p class="reading-hint">Beim Wechsel der Aufnahme oder Alija wechselt der Text mit. Du kannst den Text scrollen und die Aufnahme pausieren oder zurücksetzen.</p></div>${audioDock()}<div class="card"><h3>Passage im Siddur</h3><button class="smallbtn" data-action="open-rashash-texts">Rashash · Textbände öffnen →</button><button class="smallbtn" data-action="read-open-siddur" ${d?.sectionId!==undefined?'':'disabled'}>Im Edot-HaMizrach-Siddur öffnen →</button><details class="reading-assignment" ${readState.status==='unmapped'?'open':''}><summary>Andere Passage zuordnen</summary><label for="reading-assignment">Text für diese Aufnahme</label><select id="reading-assignment"><option value="">Passage wählen …</option><optgroup label="Psalmen"><option value="ref:Psalms 23">Psalm 23 · מזמור לדוד ה׳ רועי</option><option value="ref:Psalms 29">Psalm 29 · מזמור לדוד הבו לה׳</option></optgroup><optgroup label="Edot HaMizrach">${data.siddur.filter(s=>stripHtml(s.html).trim()).map(s=>`<option value="section:${s.id}">${esc(s.title)}</option>`).join('')}</optgroup></select><button class="smallbtn" data-action="read-bind">Für diese Aufnahme merken</button></details></div><div class="notice reading-sync-note">Der Text folgt dem Aufnahmeabschnitt. Wort- oder versgenaue Hervorhebungen benötigen geprüfte Zeitmarken. Die verfügbaren Rashash-Textbände stehen im Siddur bereit. Sie enthalten auch Kavvanot und ersetzen nicht automatisch den zusammenhängenden Aufnahme-Text.</div><button class="smallbtn" data-nav="audio">Andere Aufnahme wählen →</button></aside></div>`+footer();}
function mediaTime(seconds){if(!Number.isFinite(seconds)||seconds<0)return '–';return `${Math.floor(seconds/60)}:${String(Math.floor(seconds)%60).padStart(2,'0')}`;}
function updateReadingClock(){if(!$('#reading-time'))return;const el=audio.audio;$('#reading-time').textContent=mediaTime(el.currentTime||0);$('#reading-duration').textContent='/ '+mediaTime(el.duration);$('#reading-progress').style.width=(Number.isFinite(el.duration)&&el.duration>0?el.currentTime/el.duration*100:0)+'%';$('#reading-status').textContent=readingStatus();$('#reading-play-toggle').textContent=audio.preparing||!audio.audio.paused?'Ⅱ Pause':'▶ Fortsetzen';$('#reading-play-toggle').disabled=!audio.current;$('#reading-track-name').textContent=audio.current?.title||audio.current?.canonical||readState.descriptor?.title||'Wähle eine Aufnahme';$('#reading-queue-count').textContent=audio.current?`${audio.index+1} / ${audio.queue.length}`:'–';$('[data-action=read-previous]').disabled=!(audio.current&&audio.index>0);$('[data-action=read-next]').disabled=!(audio.current&&audio.index+1<audio.queue.length);}
function updateReadingDom(){if(!$('#reading-body'))return;const d=readState.descriptor;$('#reading-title').textContent=d?.title||audio.current?.title||'Dein Siddur zum Hören';$('#reading-source').textContent=d?.source||'Die Passage öffnet sich mit der Aufnahme.';$('#reading-body').innerHTML=readingBody();$('#reading-body').style.setProperty('--reading-size',state.readFont+'px');$('#reading-body').scrollTop=0;$('#reading-note').textContent=d?.note||'';$('#reading-original').href=d?.sourceUrl||'https://www.sefaria.org/Siddur_Edot_HaMizrach';$('[data-action=read-open-siddur]').disabled=d?.sectionId===undefined;updateReadingClock();}
async function prepareReadAlong(track){const request=++readToken;readLoader.cancel();let binding=readBindings[track.url];const descriptor=resolveReadAlong(binding?{...track,...binding}:track,{siddur:data.siddur,external:data.external,step:plan[state.stage]});readState={key:track.url,status:descriptor?'loading':'unmapped',descriptor,error:''};if(state.followAudio){if($('#modal').open)$('#modal').close();if(state.page!=='listen')navigate('listen');else updateReadingDom();}else updateReadingDom();if(!descriptor)return;try{const result=await readLoader.load(descriptor);if(request!==readToken||!result||audio.current?.url!==track.url)return;readState={key:track.url,status:'ready',descriptor:result,error:''};updateReadingDom();}catch(error){if(request!==readToken||audio.current?.url!==track.url)return;readState={key:track.url,status:'error',descriptor,error:error.name==='AbortError'?'Die Textquelle hat nicht rechtzeitig geantwortet.':error.message};updateReadingDom();}}
function changeReadingFont(delta){state.readFont=Math.max(20,Math.min(42,state.readFont+delta));$('#reading-body')?.style.setProperty('--reading-size',state.readFont+'px');$('.rashash-text-body')?.style.setProperty('--reading-size',state.readFont+'px');save();}

function audioDock(){return `<div class="audio-player" id="audio-dock" ${audio.current?'':'hidden'}><div style="display:flex;align-items:center;justify-content:space-between;gap:12px"><div><strong id="audio-title">${esc(audio.current?.title||audio.current?.label||'')}</strong><small id="audio-meta">${esc(audio.current?.label||'')}</small></div><div class="audio-indicator ${!audio.audio.paused?'playing':''}" id="audio-indicator"><i></i><i></i><i></i><i></i></div></div><div id="native-audio"></div><small id="audio-note">${esc(audio.current?.note||'')}</small><a id="audio-source" target="_blank" rel="noopener" href="${esc(audio.current?.page||'https://www.pizmonim.org/')}" style="font-size:10px">Aufnahmequelle ↗</a></div>`}
function audioPage(){const combined=[...data.uploads,...data.external.recordings];return pageTitle('Kol HaKehilla · קול הקהילה','Der Klang der Synagoge.','Deine Aufnahmen und ergänzende sefardische Lesungen direkt von der Originalquelle.')+`<div class="toolbar"><input type="search" id="audio-search" placeholder="Parascha, Gebet oder Dateiname …" aria-label="Audio suchen"><select id="audio-filter" aria-label="Audioart"><option value="all">Alle Aufnahmen</option><option value="uploaded">Deine MP3-Dateien</option><option value="torah">Tora · vollständig</option><option value="haftarah">Haftara</option><option value="prayer">Vorbeter & Gebete</option></select><button class="smallbtn" data-action="sound">${state.sound?'♪ Ton ist aktiv':'♪ Ton einschalten'}</button></div><div class="cards"><article class="card"><h3>${data.uploads.length} eigene MP3-Dateien</h3><p>Aus dem Ordner parashat. Originaldateien bleiben erhalten; die Zuordnung folgt ihren Dateinamen.</p></article><article class="card"><h3>54 Tora-Lesungen</h3><p>Abe Zami und weitere Vorleser. Dazu 378 einzelne Schabbat- und 162 Werktags-Alija-Dateien aus der Originalquelle.</p></article><article class="card"><h3>${data.external.recordings.filter(x=>x.kind==='haftarah').length} Haftara-Einträge</h3><p>Der Automat wählt Aufnahmen anhand der tatsächlichen Bibelstelle. Sonderlesungen können weiterhin eine Audiolücke haben.</p></article></div><div class="notice">Pizmonim-Aufnahmen: syrisch-sefardische Tradition, keine nachgewiesene Rashash-Vertonung. Die Künstliche Lesestimme ist optional und erzeugt keinen traditionellen Kantillationsgesang.</div><div class="audio-list" style="margin-top:17px">${combined.map((r,i)=>`<div class="audio-row" data-audio-kind="${r.kind}" data-search="${esc([r.title,r.label,r.canonical,r.description].join(' ').toLowerCase())}"><div><strong>${esc(r.canonical||r.title)}</strong><small>${esc(r.label||'Eigene Aufnahme')} · ${r.kind==='uploaded'?'Repository':r.kind==='torah'?'Tora':r.kind==='haftarah'?'Haftara':'Gebet'}</small></div><button data-audio-index="${i}">▶ Hören</button></div>`).join('')}</div>`+audioDock()+footer()}
function sourcesPage(){return pageTitle('Mesorah · מסורה','Quellen, Klang und Ordnung.','Die Herkunft jedes Textes und jeder Aufnahme bleibt nachvollziehbar.')+`<div class="two-columns"><section class="source-list"><article><h3>Siddur HaRashash</h3><p>Die neun bereitgestellten Original-PDFs sind Grundlage der Quellenansicht. Themen und PDF-Seiten wurden anhand der Scans erschlossen. Die komplette Kavvanot-Abfolge ist nicht maschinenlesbar transkribiert.</p><button data-nav="siddur" class="smallbtn">Rashash-Originale lesen →</button></article><article><h3>Siddur Edot HaMizrach</h3><p>Shaliehsaboo Edition aus deinem Textbestand, mit hebräischem Original und seinen Anweisungen. Sefaria weist die Ausgabe als CC0 aus.</p><a href="https://www.sefaria.org/Siddur_Edot_HaMizrach?tab=versions" target="_blank" rel="noopener">Sefaria · Ausgabe und Lizenz ↗</a></article><article><h3>Tora-Aufrufe und Jahreskalender</h3><p>Mischna Megilla 4:2; Schulchan Aruch, Orach Chajim 135, 282, 423, 488, 566, 621 und 685. Berechnung und Versbereiche: @hebcal/core und @hebcal/leyning; die sefardische Haftara-Variante erhält Vorrang.</p><div class="barlinks"><a href="https://www.sefaria.org/Mishnah_Megillah.4.2" target="_blank" rel="noopener">Mischna</a><a href="https://www.sefaria.org/Shulchan_Arukh%2C_Orach_Chayim.135" target="_blank" rel="noopener">Orach Chajim 135</a><a href="https://hebcal.github.io/api/leyning/" target="_blank" rel="noopener">Hebcal</a></div></article><article><h3>Sephardic Pizmonim Project</h3><p>Externe Aufnahmen werden von den Originalservern gestreamt. Namen der Vortragenden und Quellenseiten stehen am Player. Vollständige Paraschiot und Alijot: überwiegend Abe Zami; Haftara und Gebete von mehreren Vortragenden.</p><a href="https://www.pizmonim.org/section.php?maqam=Pentateuch" target="_blank" rel="noopener">Tora-Aufnahmen ↗</a> · <a href="https://www.pizmonim.org/section.php?maqam=Haftarot" target="_blank" rel="noopener">Haftarot ↗</a></article><article><h3>Die 71 Rabbiner</h3><p>Die Namen und Porträts stammen unverändert aus dem Sanhedrin-Projekt. Es handelt sich um Projektfiguren. Es werden keine echten Stimmen dieser Figuren vorgetäuscht und keine Abstammungsangaben erfunden.</p><a href="https://github.com/Moriahise/Sanhedrin/tree/main/Rav" target="_blank" rel="noopener">Porträtbestand ↗</a></article></section><section><div class="card"><h3>Deine Einstellungen</h3><div style="margin-top:15px">${dateToolbar()}</div><label class="settings-row"><input type="checkbox" id="tts-toggle" ${state.tts?'checked':''}>Künstliche hebräische Stimmen für einzelne Beter und Gemeinderufe</label><label class="settings-row"><input type="checkbox" id="upload-toggle" ${state.preferUploads?'checked':''}>Eigene Parascha-MP3s vor den vollständigen Quellaufnahmen verwenden</label><label class="settings-row"><input type="checkbox" id="fast-toggle" ${state.fastHaftara?'checked':''}>Haftara auch an kleinen Fasttagen bei Mincha (abweichender Gemeindeminhag)</label><label class="settings-row">Lautstärke <input id="volume-input" type="range" min="0" max="1" step=".05" value="${state.volume}" aria-label="Lautstärke"></label><p>Einstellungen werden nur in diesem Browser gespeichert. Stille Amida bleibt ohne automatische Audio-Wiedergabe.</p></div><div class="notice">Dies ist eine animierte Lernumgebung. Die 71 Figuren bilden einen dargestellten Minjan; ein virtueller Minjan ersetzt keine versammelten Personen. Kavvanot werden gelesen, nicht künstlich als geprüfte Rashash-Rezitation erzeugt.</div><div class="card"><h3>Was noch keine vollständige Aufnahme hat</h3><p>Mehrere Sonderlesungen und Festgebete haben bislang keine passend geprüfte Audiofassung. Teruma und Kedoschim fehlen in der erschlossenen wöchentlichen Haftara-Sammlung. Der Player zeigt fehlende Aufnahmen an und spielt dafür keine andere Haftara.</p><div class="barlinks"><a href="docs/AUDIO_QUELLEN.md" target="_blank" rel="noopener">Audio-Nachweis</a><a href="docs/RASHASH_QUELLEN.md" target="_blank" rel="noopener">Rashash-Seitenindex</a></div></div><div class="card" style="margin-top:18px"><h3>Weitere Räume</h3><p>Das Projekt folgt der Bedienordnung und den Farben von Minhal HaMikdash.</p><a href="https://moriahise.github.io/Minhal-haMikdash/app/Minhal_HaMikdash_Lebendiges_13.1.html" target="_blank" rel="noopener">Das lebendige Tempeljahr ↗</a></div></section></div>`+footer()}
function render(){const token=++renderToken;scene?.dispose();scene=null;document.getElementById('app').innerHTML=shell();$('#main').innerHTML=({home:()=>overview(),scene:()=>overview(true),prayer:prayerPage,torah:torahPage,year:calendarPage,rabbis:rabbisPage,siddur:siddurPage,listen:readAlongPage,audio:audioPage,sources:sourcesPage}[state.page]||(()=>overview()))();if(audio.current&&!$('#audio-dock'))$('#main').insertAdjacentHTML('beforeend',audioDock());attachAudio();bindInputs();if(state.page==='siddur'&&state.siddurMode==='rashash-text')loadRashashText();updateLive();updateReadingClock();if($('#scene'))requestAnimationFrame(()=>{if(token!==renderToken)return;try{scene=new SynagogueScene($('#scene'),data.rabbis,showRabbi);$('#scene-loading')?.remove();updateLive();}catch(err){console.warn('WebGL unavailable; using software perspective renderer.');const old=$('#scene'),replacement=old.cloneNode();old.replaceWith(replacement);scene=new SynagogueCanvas(replacement,data.rabbis,showRabbi);$('#scene-loading')?.remove();updateLive();}});}
function attachAudio(){const host=$('#native-audio');if(host)host.appendChild(audio.audio)}
function navigate(id){state.page=id;render();window.scrollTo({top:0,behavior:'instant'});history.replaceState(null,'','#'+id)}
function showRabbi(index){const r=data.rabbis[index];modal(r.name,`<img class="person-portrait" src="${r.portrait||r.image}" alt="${esc(r.name)}"><div class="eyebrow">Gemeindemitglied ${index+1} / 71</div><p>${index===leaderIndex()?'Heute begleitet diese Figur den Gottesdienst als Vorbeter.':'Diese Figur nimmt am Minjan der Synagoge teil.'}</p><p>Name und Porträt wurden aus dem vorhandenen Projektbestand übernommen.</p><p class="muted">Projektfigur · keine bestätigte Kohen-/Levi-Zuordnung · keine geklonte Stimme.</p><a href="${esc(r.image)}" target="_blank" rel="noopener">Originalporträt öffnen ↗</a><div style="clear:both"></div>`)}
function updateLive(){const step=plan[state.stage];if(!step)return;const idx=actorIndex();const r=data.rabbis[idx>=0?idx:leaderIndex()];if($('#live-title')){$('#live-title').textContent=step.title;$('#live-he').textContent=step.he;$('#live-actor').innerHTML=`<img src="${r.portrait||r.image}" alt="${esc(r.name)}"><div><strong>${step.actor==='community'?'Die Gemeinde':esc(r.name)}</strong><small>${step.actor==='community'?'71 Beter · gemeinsames Gebet':step.actor==='gabbai'?'Gabbai':step.actor==='reader'?'Tora-Vorleser / Aufgerufener':step.actor==='maftir'?'Maftir':'Vorbeter'}</small></div>`;$('#step-progress').style.width=stepProgress()*100+'%';$('#step-counter').textContent=`Abschnitt ${state.stage+1} / ${plan.length}`;$('#step-time').textContent=step.quiet?'Stilles Gebet':playingStep&&audio.current?(audio.audio.paused?'Aufnahme pausiert':'Aufnahme läuft'):`${Math.round(stepProgress()*100)} %`;$('#live-note').textContent=step.quiet?'Die Gemeinde betet die Amida leise. Die Audio-Wiedergabe ruht.':step.id==='torah'&&audio.current?.kind==='aliyah'?`${audio.current.title}. Die Szene folgt den aufgenommenen Alijot; die angezeigten Versgrenzen können abweichen.`:step.id==='torah'?`Die Tora wird an der Bima gelesen. ${step.reading.entries.length} Aufrufe im heutigen Ablauf.`:step.id==='haftara'?`Die sefardische Haftara: ${step.reading.haftara}.`:step.note||'Der Abschnitt lässt sich im Siddur mit seiner Originalquelle öffnen.';$('#play-btn').textContent=state.running?'Ⅱ Pause':'▶ Fortsetzen';$('#scene-action').textContent=step.title;$('#parochet-status').textContent=ritualForStep(step,stepProgress()).label;}
 if($('#header-clock'))$('#header-clock').textContent=time(state.minute);
 $$('.timeline button').forEach((b,i)=>{b.classList.toggle('active',i===state.stage);b.classList.toggle('done',i<state.stage)});
 scene?.setState(step,stepProgress(),idx,state.minute);
}
function startStep(play=true){state.waiting=false;stageTime=0;playingStep=false;manualAudio=false;audio.stop();updateLive();if(play&&state.sound&&state.running){const step=plan[state.stage];const tracks=audio.tracksForStep(step,info,state.service,state.preferUploads);if(tracks.length){playingStep=true;audio.play(tracks);}else if(!step.quiet&&state.tts&&step.speech){audio.speechEnabled=true;playingStep=audio.speak(step.speech,Math.max(0,actorIndex()),()=>{if(step.response){playingStep=audio.speak(step.response,7,()=>{playingStep=false})}else playingStep=false});}}
}
function chooseStage(i){state.stage=Math.max(0,Math.min(plan.length-1,i));startStep();if(state.page==='prayer')render();}
function nextStep(){if(state.stage+1<plan.length){state.stage++;startStep();}else if(state.mode==='year'){const sv=annualServices(info);const next=sv[sv.indexOf(state.service)+1];if(next){state.service=next;}else{state.date=isoDate(parseDate(state.date).getTime?new Date(+parseDate(state.date)+86400000):parseDate(state.date));state.minute=720;state.service='arvit';updateInfo();state.service=annualServices(info)[0];}updateInfo();render();startStep();}else if(state.mode==='live'){state.waiting=true;audio.pause();updateLive();}else{state.running=false;audio.pause();updateLive();toast('Dieser Gottesdienst ist abgeschlossen. Wähle das nächste Gebet oder starte den Jahreslauf.');}}
function audioChanged(change){if(change.current===null){readToken++;readLoader.cancel();if(readState.status==='loading')readState.status='idle';}updateReadingClock();$$('[data-action=sound]').forEach(b=>{b.textContent=state.sound?'♪ Audio aktiv':'♪ Ton einschalten';b.classList.toggle('active',state.sound)});if(change.error)toast(change.error);const c=change.current??audio.current;let dock=$('#audio-dock');if(!dock&&c&&['home','scene','prayer','torah','audio'].includes(state.page)){const x=document.createElement('div');x.innerHTML=audioDock();$('#main').appendChild(x.firstElementChild);dock=$('#audio-dock');}if(dock){dock.hidden=!c;if(c){$('#audio-title').textContent=c.title||c.canonical||c.label;$('#audio-meta').textContent=c.label||c.source||'';$('#audio-note').textContent=c.note||'Originalaufnahme · '+(c.kind==='uploaded'?'Hochgeladener Bestand':'Sephardic Pizmonim Project');$('#audio-source').href=c.page||'https://github.com/Moriahise/azara/tree/main/parashat';$('#audio-indicator').classList.toggle('playing',!audio.audio.paused);attachAudio();}}updateLive();}
function setDate(d){state.date=d;state.minute=720;state.year=new HDate(parseDate(d)).getFullYear();updateInfo();render();startStep();}
function bindInputs(){const bind=(s,event,fn)=>$(s)?.addEventListener(event,fn);bind('#rashash-text-volume','change',e=>{state.textVolume=e.target.value;state.textPage=1;render()});bind('#rashash-text-page','change',e=>{state.textPage=+e.target.value;render()});bind('#rashash-text-search','input',e=>{const query=searchableHebrew(e.target.value);let matches=0;$$('#rashash-page-catalog button').forEach(b=>{b.hidden=!b.dataset.search.includes(query);if(!b.hidden)matches++});$('#rashash-no-results').hidden=matches>0;});bind('#date-input','change',e=>{if(e.target.value)setDate(e.target.value)});bind('#region-input','change',e=>{state.il=e.target.value==='il';save();updateInfo();render()});bind('#city-input','change',e=>{state.city=e.target.value;state.il=CITIES[state.city].il;save();updateInfo();render()});bind('#mode-input','change',e=>{state.mode=e.target.value;if(state.mode==='live')syncLive();state.running=true;toast(state.mode==='year'?'Der Jahreslauf setzt nach jedem Gebet mit dem nächsten fort.':state.mode==='live'?'Datum und Tageszeit folgen jetzt dem ausgewählten Ort.':'Der aktuelle Gottesdienst läuft.');});bind('#speed-input','change',e=>{state.speed=+e.target.value;stageTime=0});bind('#year-input','keydown',e=>{if(e.key==='Enter'){state.year=Math.min(6000,Math.max(5700,+e.target.value||5787));render()}});bind('#rabbi-search','input',e=>$$('.person').forEach(b=>b.hidden=!b.dataset.search.includes(e.target.value.toLowerCase())));bind('#siddur-search','input',e=>$$('#siddur-catalog button').forEach(b=>b.hidden=!b.dataset.search.includes(e.target.value.toLowerCase())));bind('#pdf-select','change',e=>{state.pdf=e.target.value;state.pdfPage=1;render()});bind('#pdf-page','change',e=>{const doc=data.rashash.documents.find(x=>x.id===state.pdf);state.pdfPage=Math.min(doc.pages,Math.max(1,+e.target.value||1));render()});const filterAudio=()=>{const q=$('#audio-search')?.value.toLowerCase()||'',kind=$('#audio-filter')?.value||'all';$$('.audio-row').forEach(r=>r.hidden=!(r.dataset.search.includes(q)&&(kind==='all'||kind===r.dataset.audioKind)));};bind('#audio-search','input',filterAudio);bind('#audio-filter','change',filterAudio);bind('#tts-toggle','change',e=>{state.tts=e.target.checked;audio.speechEnabled=state.tts;save();toast(state.tts?'Künstliche hebräische Lesestimmen aktiviert.':'Künstliche Lesestimmen deaktiviert.')});bind('#upload-toggle','change',e=>{state.preferUploads=e.target.checked;save()});bind('#fast-toggle','change',e=>{state.fastHaftara=e.target.checked;save();updateInfo();render()});bind('#follow-toggle','change',e=>{state.followAudio=e.target.checked;save()});bind('#volume-input','input',e=>{state.volume=+e.target.value;audio.volume=state.volume;audio.audio.volume=state.volume});}
function selectTextForStep(){const step=plan[state.stage];let candidates=data.siddur.filter(s=>s.title===step.textTitle);const ranges=state.service==='mincha'?[30,34]:state.service==='arvit'?(info.shabbat?[44,48]:[34,38]):info.shabbat?[60,76]:[7,27];let section=candidates.find(s=>s.id>=ranges[0]&&s.id<=ranges[1])||candidates[0];if(!section&&step.id==='amida'&&info.shabbat&&state.service==='mincha')section=data.siddur.find(s=>s.html.includes('אַתָּה אֶחָד'));if(!section)return null;return section;}
function openCurrentText(){const sec=selectTextForStep();const step=plan[state.stage];const doc=bestRashash(step);const textId=doc.id;const textDoc=data.rashash.documents.find(d=>d.id===textId&&hasRashashTextPage(d.transcription,doc.page));modal(step.title,`<div class="barlinks">${textDoc?`<button class="smallbtn" data-open-rashash-text="${textId}" data-page="${doc.page}">Rashash · Text mit Niqqud öffnen →</button>`:''}<button class="smallbtn" data-open-rashash="${doc.id}" data-page="${doc.page}">Rashash · Originalseite ${doc.page} ↗</button>${sec?`<button class="smallbtn" data-open-section="${sec.id}">Edot-HaMizrach-Text öffnen →</button>`:''}</div>${sec?`<div class="notice">Ergänzender Nusach Edot HaMizrach · Shaliehsaboo Edition. Die Rashash-Kavvanot stehen separat im Original.</div><div class="reader"><h3>${esc(sec.title)}</h3><div class="reader-body">${sec.html}</div></div>`:`<div class="notice">Dieser Festabschnitt ist im gelieferten Edot-HaMizrach-Text nicht vollständig enthalten. Lies die zugehörige Rashash-Originalquelle. Es wird kein Ersatztext als Rashash ausgegeben.</div>`}`)}
function bestRashash(step){if(info.kippur)return {id:'21722',page:state.service==='shacharit'?126:1};if(info.hd.getMonth()===7&&info.hd.getDate()<=2)return {id:'21721',page:state.service==='musaf'?147:state.service==='mincha'?161:3};if(info.hd.getMonth()===3&&info.chag)return {id:'21518',page:state.service==='musaf'?22:18};if(info.hd.getMonth()===7&&(info.chag||info.chol))return {id:'21723',page:step.id==='hallel'?18:1};if(info.shabbat)return state.service==='arvit'||state.service==='kabbalat'?{id:'21519',page:state.service==='arvit'?19:3}:{id:'21521',page:state.service==='musaf'?217:state.service==='mincha'?221:1};if(state.service==='shacharit'&&['blessings','korbanot','ketoret-end'].includes(step?.id))return {id:'21376',page:step.id==='blessings'?19:153};return {id:'21375',page:state.service==='mincha'?318:state.service==='arvit'?320:step.id==='torah'?270:step.id==='repetition'?223:step.id==='shema'?54:3};}
let textRequest=0;async function readRef(ref){const token=++textRequest;modal(ref,`<div class="notice">Hebräischer Originaltext wird von Sefaria geladen …</div><a href="https://www.sefaria.org/${encodeURIComponent(ref)}" target="_blank" rel="noopener">Text direkt in Sefaria öffnen ↗</a>`);try{const parts=ref.split(/;\s*/);const texts=[];for(const p of parts){const res=await fetch('https://www.sefaria.org/api/texts/'+encodeURIComponent(p)+'?context=0&commentary=0');if(!res.ok)throw Error();const body=await res.json();if(body.error)throw Error();texts.push({ref:p,body});}if(token!==textRequest||!$('#modal').open)return;modal(ref,`<div class="source-line">Hebräischer Originaltext · Sefaria · <a href="https://www.sefaria.org/${encodeURIComponent(ref)}" target="_blank" rel="noopener">Quelle und Ausgabe ↗</a></div>${texts.map(t=>`<h3>${esc(t.ref)}</h3><div class="he" id="bible-text">${t.body.he.flat(Infinity).map(x=>`<p>${esc(stripHtml(x))}</p>`).join('')}</div>`).join('')}<button data-action="speak-bible">♪ Künstliche Lesestimme</button>`);}catch{if(token!==textRequest)return;modal(ref,`<div class="notice">Der Originaltext konnte momentan nicht geladen werden. Die bestätigte Bibelstelle und die direkte Quelle bleiben verfügbar.</div><a href="https://www.sefaria.org/${encodeURIComponent(ref)}" target="_blank" rel="noopener">${esc(ref)} in Sefaria lesen ↗</a>`);}}
function enableSound(){state.sound=true;audio.enable();toast('Ton aktiviert. Originalaufnahmen starten beim passenden Abschnitt.');startStep();}
function playManual(tracks){if(!tracks.length){toast('Für diesen genauen Abschnitt ist noch keine passende Aufnahme zugeordnet. Der Text bleibt verfügbar.');return;}state.sound=true;audio.enable();manualAudio=true;playingStep=false;state.running=false;audio.play(tracks);updateLive();}
function syncLive(){const n=zonedNow(state.city);const changed=n.date!==state.date||Math.abs(n.minute-state.minute)>0;state.date=n.date;state.minute=n.minute;if(changed){const old=info.hd.abs();info=dayInfo(state.date,state.il,state.minute,state.city);const morningEnd=(info.zman.sunrise||360)+15+servicePlan(info,'shacharit').reduce((n,s)=>n+s.minutes,0);const available=servicesFor(info).map(x=>x[0]);const svc=info.evening||state.minute<(info.zman.dawn||300)?'arvit':info.kippur&&state.minute>=(info.zman.sunset||1080)-45?'neilah':state.minute>=(info.zman.mincha||900)?'mincha':available.includes('musaf')&&state.minute>=morningEnd?'musaf':available.includes('selichot')&&state.minute<(info.zman.sunrise||360)?'selichot':'shacharit';if(old!==info.hd.abs()||svc!==state.service){state.service=svc;updateInfo();render();startStep();}else updateLive();}}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-nav],a[data-nav]');if(!b)return;if(b.dataset.nav){navigate(b.dataset.nav);return;}if(b.dataset.service){state.service=b.dataset.service;updateInfo();render();startStep();return;}if(b.dataset.stage!==undefined){chooseStage(+b.dataset.stage);return;}if(b.dataset.camera){scene?.setView(b.dataset.camera);return;}if(b.dataset.rabbi!==undefined){showRabbi(+b.dataset.rabbi);return;}if(b.dataset.date){setDate(b.dataset.date);navigate('home');return;}if(b.dataset.yearDelta){state.year+=+b.dataset.yearDelta;render();return;}if(b.dataset.rashashTextPage){state.textPage=+b.dataset.rashashTextPage;render();return;}if(b.dataset.openRashashText){openRashashText(b.dataset.openRashashText,+b.dataset.page||1);return;}if(b.dataset.siddurMode){state.siddurMode=b.dataset.siddurMode;render();return;}if(b.dataset.section!==undefined){state.section=+b.dataset.section;render();return;}if(b.dataset.pdfPage){state.pdfPage=+b.dataset.pdfPage;render();return;}if(b.dataset.openRashash){state.pdf=b.dataset.openRashash;state.pdfPage=+b.dataset.page;state.siddurMode='rashash';$('#modal').close();navigate('siddur');return;}if(b.dataset.openSection){state.section=+b.dataset.openSection;state.siddurMode='edot';$('#modal').close();navigate('siddur');return;}if(b.dataset.readRef){readRef(b.dataset.readRef);return;}if(b.dataset.audioIndex!==undefined){playManual([[...data.uploads,...data.external.recordings][+b.dataset.audioIndex]]);return;}if(b.dataset.aliyah){const rd=readingsFor(info,state.service,state.fastHaftara)[0];const source=data.external.torahAliyot.find(x=>normalize(x.canonical)===normalize(rd?.parsha?.[0]));const url=source?.[state.service==='mincha'||rd.type==='weekday'?'weekday':'shabbat']?.[b.dataset.aliyah];playManual(url?[{title:`${rd.name.en} · ${b.dataset.aliyah==='M'?'Maftir':'Alija '+b.dataset.aliyah}`,url,label:'Abe Zami · syrisch-sefardische Einteilung',note:'Alija-Versgrenzen der Audioquelle wurden nicht mit dem Kalender abgeglichen.',page:'https://www.pizmonim.org/section.php?maqam=Pentateuch'}]:[]);return;}
 switch(b.dataset.action){case'rashash-text-prev':moveRashashText(-1);break;case'rashash-text-next':moveRashashText(1);break;case'rashash-text-retry':rashashTextErrors.delete(state.textVolume);render();break;case'open-rashash-texts':openRashashText(state.textVolume,state.textPage);break;case'read-toggle':if(audio.audio.paused&&!audio.preparing){if(!manualAudio)state.running=true;audio.resume();}else{state.running=false;audio.pause();}updateReadingClock();break;case'read-previous':if(!manualAudio)state.running=true;audio.skipTo(audio.index-1);break;case'read-next':if(!manualAudio)state.running=true;audio.skipTo(audio.index+1);break;case'read-retry':if(audio.current)prepareReadAlong(audio.current);break;case'read-smaller':changeReadingFont(-2);break;case'read-larger':changeReadingFont(2);break;case'read-open-siddur':if(readState.descriptor?.sectionId!==undefined){state.siddurMode='edot';state.section=readState.descriptor.sectionId;navigate('siddur');}break;case'read-bind':{const value=$('#reading-assignment')?.value;if(!audio.current||!value){toast('Bitte eine Passage und eine Aufnahme wählen.');break;}const binding=value.startsWith('section:')?{sectionId:+value.slice(8)}:{textRef:value.slice(4)};readBindings[audio.current.url]=binding;try{localStorage.setItem('azara-reading-bindings',JSON.stringify(readBindings))}catch{}prepareReadAlong(audio.current);toast('Die Passage ist dieser Aufnahme zugeordnet.');break;}case'menu':$('.sidebar').classList.toggle('open');break;case'today':{const n=zonedNow(state.city);state.date=n.date;state.minute=n.minute;updateInfo();render();startStep();break;}case'calendar':navigate('year');break;case'load-year':state.year=Math.min(6000,Math.max(5700,+$('#year-input').value||5787));render();break;case'shabbat':state.minute=540;state.date=nextShabbatDate();state.service='shacharit';updateInfo();navigate('home');startStep();break;case'prev-day':setDate(isoDate(new Date(+parseDate(state.date)-86400000)));break;case'next-day':setDate(isoDate(new Date(+parseDate(state.date)+86400000)));break;case'play':state.running=!state.running;if(state.running){if(audio.current)audio.resume();else startStep();}else audio.pause();updateLive();break;case'next-step':nextStep();break;case'restart':state.stage=0;state.running=true;startStep();break;case'sound':if(state.sound){state.sound=false;audio.stop();playingStep=false;toast('Audio ausgeschaltet.');}else enableSound();$$('[data-action=sound]').forEach(x=>x.textContent=state.sound?'♪ Audio aktiv':'♪ Ton einschalten');break;case'current-text':openCurrentText();break;case'torah-start':{const index=plan.findIndex(x=>x.id==='torah');if(index>=0){state.stage=index;state.running=true;navigate('scene');enableSound();}break;}case'haftara-audio':{const r=readingsFor(info,state.service,state.fastHaftara)[0];playManual(audio.tracksForStep({id:'haftara',reading:r},info,state.service));break;}case'run-year':state.date=isoDate(new HDate(1,7,state.year).greg());state.minute=720;state.mode='year';state.service='arvit';state.running=true;updateInfo();navigate('home');startStep();toast('Der Jahreslauf beginnt am 1. Tischri '+state.year+'.');break;case'speak-section':state.sound=true;audio.enable();audio.speechEnabled=true;audio.speak(data.siddur[state.section].html,leaderIndex());break;case'speak-bible':state.sound=true;audio.enable();audio.speechEnabled=true;audio.speak($$('#modal-body .he').map(x=>x.textContent).join(' '),leaderIndex());break;case'stop-audio':audio.stop();playingStep=false;break;}
});
async function init(){const [rabbis,assets,external,rashash,siddur]=await Promise.all(['rabbis.json','repository-assets.json','audio-external.json','rashash.json','siddur.json'].map(getJson));data={rabbis,assets,external,rashash,siddur,uploads:uploadsFromAssets(assets)};audio=new SynagogueAudio(external,data.uploads,audioChanged,()=>{playingStep=false;if(!manualAudio&&state.running){if(state.tts){audio.speechEnabled=true;playingStep=audio.speak('אמן',Math.max(0,actorIndex()+1),()=>{playingStep=false;if(state.running)nextStep()});if(!playingStep)nextStep();}else nextStep();}});audio.beforePlay=prepareReadAlong;audio.onTime=updateReadingClock;audio.speechEnabled=state.tts;const hash=location.hash.slice(1);if(NAV.some(x=>x[0]===hash))state.page=hash;updateInfo();render();let last=performance.now(),uiElapsed=0;setInterval(()=>{const t=performance.now(),dt=Math.min((t-last)/1000,2);last=t;if(state.mode==='live'&&uiElapsed>10){uiElapsed=0;syncLive();}if(state.running&&!state.waiting&&!playingStep&&!manualAudio){stageTime+=dt;if(stepProgress()>=1)nextStep();}uiElapsed+=dt;updateLive();},500);window.azara={state,get scene(){return scene},get info(){return info},get plan(){return plan},get audio(){return audio},navigate,setDate,get data(){return data}};}
init().catch(e=>{console.error(e);$('#app').innerHTML=`<div class="loading"><span>עזרה</span><h1>Die Quellen konnten nicht geladen werden.</h1><p>${esc(e.message)}</p><button onclick="location.reload()">Erneut laden</button></div>`});
